const results = [];
for (const item of $input.all()) {
  const raw = item.json;
  if (!raw.title) continue;

  let imageUrl = null;
  if (raw.enclosure && raw.enclosure.url) {
    imageUrl = raw.enclosure.url;
  } else if (raw['media:content'] && raw['media:content'].$ && raw['media:content'].$.url) {
    imageUrl = raw['media:content'].$.url;
  } else if (raw['media:thumbnail'] && raw['media:thumbnail'].$ && raw['media:thumbnail'].$.url) {
    imageUrl = raw['media:thumbnail'].$.url;
  }

  const rawContent = (raw.contentSnippet || raw.content || raw.summary || raw.description || '').replace(/<[^>]*>?/gm, '');

  results.push({
    json: {
      source_type: 'rss',
      source_url: raw.link || raw.guid || '',
      original_title: raw.title || '',
      original_content: rawContent,
      image_url: imageUrl
    }
  });
}
return results;

