const original = $('Extract & Normalize Feed').item.json;
const aiRaw = $input.first().json.choices[0].message.content;

let parsedAi = {};
try {
  parsedAi = JSON.parse(aiRaw.trim());
} catch (e) {
  const jsonMatch = aiRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedAi = JSON.parse(jsonMatch[0]);
  } else {
    parsedAi = {
      title: original.original_title,
      content: original.original_content
    };
  }
}

return [{
  json: {
    source_type: original.source_type,
    source_url: original.source_url,
    original_title: original.original_title,
    original_content: original.original_content,
    ai_title: parsedAi.title || original.original_title,
    ai_content: parsedAi.content || original.original_content,
    image_url: original.image_url,
    status: 'PENDING',
    target_platforms: JSON.stringify(['telegram', 'wordpress'])
  }
}];
